CREATE TABLE events (
    id        BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    happened  TIMESTAMPTZ NOT NULL DEFAULT now(),
    local_wall TIMESTAMP   -- wall clock; meaning depends on the reader
);

INSERT INTO events (happened, local_wall) VALUES ('2026-03-08 07:30:00Z', '2026-03-08 02:30');

SET TimeZone = 'UTC';
SELECT happened, local_wall FROM events;

SET TimeZone = 'America/New_York';
SELECT happened, local_wall FROM events;   -- happened shifts to 02:30-05; local_wall does not

-- Extract a component in a chosen zone
SELECT (happened AT TIME ZONE 'Europe/London') AS london_wall FROM events;

SHOW TimeZone;   -- current session setting

SELECT to_char(now(), 'YYYY-MM-DD"T"HH24:MI:SSOF')        AS iso8601,
       to_char(now(), 'FMDay, FMMonth FMDD, YYYY')         AS pretty;

-- Parse with an explicit format so locale settings cannot change the meaning
SELECT to_timestamp('03/15/2026 14:30', 'MM/DD/YYYY HH24:MI') AS parsed;

-- Half-open month window: the index-friendly way to filter a time range
SELECT count(*) FROM events
WHERE happened >= '2026-03-01 00:00:00+00'
  AND happened <  '2026-04-01 00:00:00+00';

-- Time zones are IANA names, never fixed offsets
SELECT now() AT TIME ZONE 'Asia/Kolkata';

SELECT make_interval(days => 30, hours => 6);
